package com.pratik.imagetap;
import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SessionPresetTest {
 @Test public void manualAndQuickPauseAreIndependent(){SessionPause p=new SessionPause();p.beginQuick();assertTrue(p.paused());p.endQuick();assertFalse(p.paused());p.toggle();p.beginQuick();p.endQuick();assertTrue(p.paused());p.toggle();assertFalse(p.paused());p.beginQuick();p.reset();assertFalse(p.paused());}
 @Test public void presetCopiesPreserveOptionsAndIsolateEdits()throws Exception{Context c=RuntimeEnvironment.getApplication();Bitmap b=Bitmap.createBitmap(20,20,Bitmap.Config.ARGB_8888);b.eraseColor(Color.RED);File original=TargetStore.save(c,b);new TargetOptions(false,1080,new RegionRules.Region(.5f,0,1,.4f,75),"Close").save(c,original);PresetStore.copyCurrent(c,1,"Game two");assertEquals(0,PresetStore.active(c));PresetStore.open(c,1);File copy=TargetStore.files(c).get(0);assertEquals("Game two",PresetStore.name(c,1));assertEquals("Close",TargetOptions.load(c,copy).name);assertFalse(TargetOptions.load(c,copy).enabled);new TargetOptions(true,0,null,"Different").save(c,copy);assertFalse(TargetOptions.load(c,original).enabled);copy.delete();PresetStore.open(c,0);assertTrue(original.isFile());assertEquals(1,TargetStore.files(c).size());PresetStore.open(c,2);assertTrue(TargetStore.files(c).isEmpty());b.recycle();}
 @Test public void invalidSaveDoesNotReplaceSlot()throws Exception{Context c=RuntimeEnvironment.getApplication();Bitmap b=Bitmap.createBitmap(20,20,Bitmap.Config.ARGB_8888);b.eraseColor(Color.BLUE);File f=TargetStore.save(c,b);PresetStore.copyCurrent(c,1,"Backup");String before=PresetStore.folder(c,1).getPath();try{PresetStore.copyCurrent(c,1,"  ");fail();}catch(IOException expected){}assertEquals(before,PresetStore.folder(c,1).getPath());assertTrue(f.exists());b.recycle();}
 @Test public void popupHeightDoesNotFollowStatusAndPauseInvalidates()throws Exception{org.robolectric.android.controller.ServiceController<TapService> ctl=Robolectric.buildService(TapService.class).create();TapService svc=ctl.get();set(svc,"wm",svc.getSystemService(Context.WINDOW_SERVICE));set(svc,"prefs",svc.getSharedPreferences("config",0));invoke(svc,"showPanel");LinearLayout panel=(LinearLayout)get(svc,"panel");TextView status=(TextView)get(svc,"status");status.setText("Scanning…");int first=height(panel);status.setText("All 500 checked · 10000ms\nClosest 99.0% / need 100%\nMore status information");assertEquals(first,height(panel));((TextView)get(svc,"scanStats")).setText("All 500 checked · 10000 ms");assertEquals(first,height(panel));panel.layout(0,0,528,first);Bitmap preview=Bitmap.createBitmap(528,first,Bitmap.Config.ARGB_8888);panel.draw(new Canvas(preview));File output=new File("build/ui-previews/floating64.png");output.getParentFile().mkdirs();try(FileOutputStream stream=new FileOutputStream(output)){preview.compress(Bitmap.CompressFormat.PNG,100,stream);}preview.recycle();set(svc,"running",true);int before=(Integer)get(svc,"generation");svc.togglePause();assertTrue(((SessionPause)get(svc,"pause")).manual);assertTrue((Integer)get(svc,"generation")>before);assertEquals("Resume",((Button)get(svc,"pauseButton")).getText().toString());assertTrue(svc.getSharedPreferences("config",0).getBoolean("sessionPaused",false));svc.stopSession("test");assertFalse(svc.getSharedPreferences("config",0).getBoolean("sessionPaused",true));ctl.destroy();}
 @Test public void finishingQuickEditorPreservesManualPause()throws Exception{TapService svc=Robolectric.buildService(TapService.class).create().get();TapService.instance=svc;SessionPause pause=(SessionPause)get(svc,"pause");pause.manual=true;pause.beginQuick();org.robolectric.android.controller.ActivityController<MainActivity> activity=Robolectric.buildActivity(MainActivity.class).create();set(activity.get(),"quickFlow",true);activity.get().finish();activity.destroy();assertFalse(pause.quick);assertTrue(pause.manual);TapService.instance=null;}
 @Test public void presetsDialogRendersThreeSlots()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();PresetEditor.open(a,()->{});Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();android.app.AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();View view=dialog.getWindow().getDecorView();view.measure(View.MeasureSpec.makeMeasureSpec(760,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1100,View.MeasureSpec.AT_MOST));view.layout(0,0,760,view.getMeasuredHeight());Bitmap b=Bitmap.createBitmap(760,view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(b));File file=new File("build/ui-previews/presets64.png");file.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(file)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();dialog.dismiss();a.finish();}
 static int height(View v){v.measure(View.MeasureSpec.makeMeasureSpec(528,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1400,View.MeasureSpec.AT_MOST));return v.getMeasuredHeight();}
 static Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}static void set(Object o,String n,Object x)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,x);}static void invoke(Object o,String n)throws Exception{Method m=o.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(o);}
}
